Interface Shape
  Method Area() As Real;
EndInterface

Class Rectangle Implements Shape
  Define rectLength, width As Real;
  Method Constructor(l As Real, a As Real)
    This.rectLength <- l;
    This.width <- a;
  EndMethod
  Method Area() As Real
    Return This.rectLength * This.width;
  EndMethod
EndClass

Class Square Implements Shape
  Define side As Real;
  Method Constructor(l As Real)
    This.side <- l;
  EndMethod
  Method Area() As Real
    Return This.side * This.side;
  EndMethod
EndClass

Class Triangle Implements Shape
  Define base, height As Real;
  Method Constructor(b As Real, a As Real)
    This.base <- b;
    This.height <- a;
  EndMethod
  Method Area() As Real
    Return This.base * This.height / 2;
  EndMethod
EndClass

Subroutine AreaOf<T: Shape>(shape As T) As Real
  Return shape.Area();
EndSubroutine

Algorithm Shapes
  Define tipo As String;
  Define sizeOne, sizeTwo As Real;
  Read tipo;
  If tipo = "square" Then
    Read sizeOne;
    Write AreaOf(New Square(sizeOne));
  Else
    Read sizeOne;
    Read sizeTwo;
    If tipo = "rectangle" Then
      Write AreaOf(New Rectangle(sizeOne, sizeTwo));
    Else
      Write AreaOf(New Triangle(sizeOne, sizeTwo));
    EndIf
  EndIf
EndAlgorithm
